data class Node(val x: Int, val y: Int, val step: Int)

fun bfs(startX: Int, startY: Int, targetX: Int, targetY: Int, vis: Array<IntArray>): Int {
    val q = ArrayDeque<Node>()
    q.add(Node(startX, startY, 0))
    vis[startX][startY] = 1
    val dirs = arrayOf(intArrayOf(0, 1), intArrayOf(1, 0), intArrayOf(0, -1), intArrayOf(-1, 0))

    while (q.isNotEmpty()) {
        val cur = q.removeFirst()
        if (cur.x == targetX && cur.y == targetY) {
            return cur.step
        }
        for (dir in dirs) {
            val nx = cur.x + dir[0]
            val ny = cur.y + dir[1]
            if (nx < 0 || ny < 0 || nx >= 110 || ny >= 110) continue
            if (vis[nx][ny] == 1) continue
            vis[nx][ny] = 1
            q.add(Node(nx, ny, cur.step + 1))
        }
    }
    return -1
}

